BEGIN;
CREATE FUNCTION pg_temp.ok(value boolean,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF value IS DISTINCT FROM true THEN RAISE EXCEPTION 'FAIL: %',label; END IF; RAISE NOTICE 'PASS: %',label; END $$;
SELECT pg_temp.ok(NOT has_function_privilege('anon','public.edv9_last_queue_begin(text)','EXECUTE'),'anonymous scheduler ticket access denied');
SELECT pg_temp.ok(NOT has_function_privilege('authenticated','public.edv9_last_queue_claim(uuid)','EXECUTE'),'rider cannot claim backend queue');
SELECT pg_temp.ok((SELECT bool_and(relrowsecurity) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='ed_last_stage' AND c.relkind='r'),'RLS for all new tables');
SELECT pg_temp.ok(NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname LIKE 'edv9_last_queue_%' AND prosecdef),'all queue RPCs SECURITY INVOKER');
SET LOCAL ROLE service_role;
INSERT INTO ed_last_stage.locations(location_id,organization_id,tenant_id,enabled) VALUES('11111111-1111-4111-8111-111111111111','22222222-2222-4222-8222-222222222222','33333333-3333-4333-8333-333333333333',true);
INSERT INTO ed_last_stage.queue_routes(location_id,source_kind,enabled,expires_at) VALUES('11111111-1111-4111-8111-111111111111','sandbox',true,now()+interval '1 hour');
UPDATE ed_last_stage.queue_control SET enabled=true;
SELECT public.edv9_last_receive('11111111-1111-4111-8111-111111111111','22222222-2222-4222-8222-222222222222','{"id":"queue-test","type":"tab:updated","data":{"id":"44444444-4444-4444-8444-444444444444"}}');
SELECT pg_temp.ok(public.edv9_last_queue_claim('11111111-1111-4111-8111-111111111111') IS NULL,'sandbox requires independent approval switch');
UPDATE ed_last_stage.queue_routes SET source_kind='synthetic';
DO $$ DECLARE claim jsonb; run uuid; result jsonb; BEGIN
 INSERT INTO ed_last_stage.queue_runs(token_hash) VALUES(repeat('a',64)) RETURNING id INTO run;
 result=public.edv9_last_queue_begin(repeat('a',64));
 PERFORM pg_temp.ok(jsonb_array_length(result->'routes')=1,'due synthetic location selected');
 PERFORM pg_temp.ok(public.edv9_last_queue_begin(repeat('a',64)) IS NULL,'ticket replay denied atomically');
 claim=public.edv9_last_queue_claim('11111111-1111-4111-8111-111111111111');
 PERFORM pg_temp.ok(claim IS NOT NULL,'approved route claims persisted work');
 PERFORM pg_temp.ok(public.edv9_last_queue_claim('11111111-1111-4111-8111-111111111111') IS NULL,'second worker cannot claim same location');
 UPDATE ed_last_stage.events SET lease_until=now()-interval '1 minute';
 UPDATE ed_last_stage.locations SET lease_until=now()-interval '1 minute',next_request_at=now()-interval '1 second';
 PERFORM pg_temp.ok(public.edv9_last_queue_claim('11111111-1111-4111-8111-111111111111')->>'lease_token' IS DISTINCT FROM claim->>'lease_token','expired claim recovered with new fencing token');
 PERFORM pg_temp.ok(public.edv9_last_queue_finish(run,'{"processed":1,"customer_name":"must not persist"}'::jsonb),'run completion accepted');
 PERFORM pg_temp.ok((SELECT NOT(report ? 'customer_name') FROM ed_last_stage.queue_runs WHERE id=run),'run report strips unexpected private fields');
 PERFORM pg_temp.ok(NOT public.edv9_last_queue_finish(run,'{}'),'run cannot be completed twice');
END $$;
UPDATE ed_last_stage.queue_routes SET expires_at=now()-interval '1 minute';
SELECT pg_temp.ok(public.edv9_last_queue_claim('11111111-1111-4111-8111-111111111111') IS NULL,'expired synthetic approval stops processing');
INSERT INTO ed_last_stage.queue_runs(token_hash,expires_at) VALUES(repeat('b',64),now()-interval '1 second');
SELECT pg_temp.ok(public.edv9_last_queue_begin(repeat('b',64)) IS NULL,'expired ticket denied');
RESET ROLE;
SELECT pg_temp.ok((SELECT count(*)=0 FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='ed_last_stage' AND NOT t.tgisinternal),'no messaging or operational triggers');
ROLLBACK;
